-- Append-only operational intelligence. Original AI rows remain preserved and copied below.
CREATE TABLE intelligence_runs (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), requester_id TEXT NOT NULL REFERENCES members(id),
 page_id TEXT REFERENCES pages(id), kind TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','needs-review','paused','completed','failed','cancelled')),
 stage TEXT NOT NULL DEFAULT 'generation', revision_id TEXT NOT NULL, input_json TEXT NOT NULL, refs_json TEXT NOT NULL DEFAULT '[]', audience_json TEXT NOT NULL DEFAULT '[]',
 skill_revision_id TEXT, parent_id TEXT REFERENCES intelligence_runs(id), output_json TEXT, failure_reason TEXT,
 provider TEXT, model TEXT, route_reason TEXT, reserved_micros INTEGER NOT NULL DEFAULT 0 CHECK(reserved_micros>=0), cost_micros INTEGER NOT NULL DEFAULT 0 CHECK(cost_micros>=0),
 tokens INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, started_at TEXT, deadline_at TEXT, retry_until TEXT, next_at TEXT, lease_id TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, settled_at TEXT
);
CREATE INDEX intelligence_runs_due ON intelligence_runs(status,next_at);
INSERT INTO intelligence_runs(id,workspace_id,requester_id,kind,status,revision_id,input_json,refs_json,output_json,provider,model,reserved_micros,cost_micros,tokens,attempts,started_at,created_at,updated_at,settled_at)
SELECT id,workspace_id,requester_member_id,feature,state,id,input_json,input_revisions_json,proposal_json,provider,model,reserved_micros,COALESCE(cost_micros,0),COALESCE(tokens,0),attempt_count,started_at,created_at,created_at,settled_at FROM ai_runs;
CREATE TABLE intelligence_revisions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,entity_kind TEXT NOT NULL,entity_id TEXT NOT NULL,content_json TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE intelligence_budgets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES intelligence_runs(id),month TEXT NOT NULL,provider TEXT NOT NULL,skill_revision_id TEXT,reserved_micros INTEGER NOT NULL CHECK(reserved_micros>=0),charged_micros INTEGER NOT NULL DEFAULT 0 CHECK(charged_micros>=0),released_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX intelligence_budgets_month ON intelligence_budgets(workspace_id,month);
INSERT INTO intelligence_budgets SELECT r.id,r.workspace_id,r.ai_run_id,r.month,COALESCE(a.provider,'legacy'),NULL,r.reserved_micros,COALESCE(a.cost_micros,0),r.released_at,r.created_at FROM ai_budget_reservations r JOIN ai_runs a ON a.id=r.ai_run_id;
CREATE TABLE intelligence_model_policy(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),revision_id TEXT NOT NULL,policy_json TEXT NOT NULL,owner_id TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE intelligence_grants(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,owner_id TEXT NOT NULL,subject_id TEXT NOT NULL,kind TEXT NOT NULL,scope_json TEXT NOT NULL,scope_hash TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,revision_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE intelligence_effects(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES intelligence_runs(id),operation_key TEXT NOT NULL,request_hash TEXT NOT NULL,grant_id TEXT NOT NULL REFERENCES intelligence_grants(id),operation TEXT NOT NULL,account_id TEXT NOT NULL,intent_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('prepared','dispatched','uncertain','confirmed','failed','cancelled')),receipt_json TEXT,observed_json TEXT,failure_reason TEXT,revision_id TEXT NOT NULL,intent_at TEXT NOT NULL,dispatched_at TEXT,confirmed_at TEXT,UNIQUE(workspace_id,operation_key));
CREATE TABLE intelligence_stages(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES intelligence_runs(id),stage TEXT NOT NULL,state TEXT NOT NULL,result_json TEXT,started_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE intelligence_skills(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,page_id TEXT NOT NULL REFERENCES pages(id),owner_id TEXT NOT NULL,name TEXT NOT NULL,current_revision_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE intelligence_skill_versions(id TEXT PRIMARY KEY,skill_id TEXT NOT NULL REFERENCES intelligence_skills(id),state TEXT NOT NULL CHECK(state IN ('draft','evaluated','active','superseded','retired')),definition_json TEXT NOT NULL,evaluation_id TEXT,authority_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE intelligence_evaluations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,skill_revision_id TEXT NOT NULL,case_hash TEXT NOT NULL,result_json TEXT NOT NULL,passed INTEGER NOT NULL CHECK(passed IN (0,1)),created_at TEXT NOT NULL);
CREATE TABLE intelligence_inquiries(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,page_id TEXT NOT NULL REFERENCES pages(id),owner_id TEXT NOT NULL,question TEXT NOT NULL,revision_id TEXT NOT NULL,refs_json TEXT NOT NULL,audience_json TEXT NOT NULL,interim_json TEXT,method_revision_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
