CREATE TRIGGER search_fts_update AFTER UPDATE ON search_text BEGIN DELETE FROM search_fts WHERE rowid=OLD.rowid; INSERT INTO search_fts(rowid,tokens) VALUES(NEW.rowid,NEW.tokens); END;

